        scan_btn: 'Scan & open report', scanning: 'Scanning...', active: 'active',
        btn_reopen_report: 'Open report again', btn_download_html: 'Download HTML',
        sca_sources: 'Data sources: OSV.dev, FIRST EPSS, CISA KEV, endoflife.date. Full Docker image scanning (OS packages inside the image, like Trivy/Harbor) needs Docker and can\'t run in the browser. Use <code>scan_sca_docker.ps1</code> for that.',
        dast_intro: 'Enter public site URLs (several allowed, space-separated, max 10). Results open as an HTML report in a new tab: MDN Observatory grade + response header analysis (HSTS, CSP, cookies, etc.), plus passive domain &amp; port info (DNS + Shodan InternetDB).',
        dast_check_btn: 'Check & open report', dast_checking: 'Checking...',
        dast_net_opt: 'Add domain &amp; port info (DNS + Shodan InternetDB — open ports &amp; known CVEs, passive, no direct nmap)',
        dast_note: 'This check is passive (it only reads public responses + existing databases), not active DAST/nmap — no packets are sent to the target. Ports &amp; CVEs come from Shodan InternetDB (a previous Shodan scan) for the DNS-resolved IP; they may be stale. Local/internal/VPN hosts are unreachable. Free HackerTarget is limited to ±50 requests/day. Only check sites you own or are authorized to test.',
        run_here: 'Run here', running: 'Running...', stop: 'Stop', copy_csv: 'Copy CSV', copied: 'Copied', copy_script: 'Copy script',
        opt1_head: 'Option 1 — Hit directly from this page', opt2_head: 'Option 2 — Script in the target app tab',
        opt2_desc: 'If Option 1 is blocked by CORS or needs the session cookie, install this script in the target app tab (like the Hook tab): it runs <i>same-origin</i>, cookies included automatically.',
        drag_bookmark: '📌 Drag to bookmarks', bookmark_msg: 'Drag this button to your browser bookmarks bar (do not click it here). Then, while on the target tab, click it from the bookmarks bar.',
